-- Initial published site_auth documents and the shipped consent form snapshot.
-- Source PDFs: apps/site/public/documents/legal/*-consent-2026-09-22.pdf.
-- Preserve any already published revision; never create user consent here.
WITH artifacts AS (
  SELECT decode('', 'base64') AS form_bytes
), revisions(kind, id, document_title, document_base64, document_sha256) AS (
  VALUES
    ('personal_data'::consent_kind, 'site-auth-personal-data-2026-09-22-v1', 'Согласие на обработку персональных данных', '', '2bcc3ad4efe2a3f94f6b88a6f399d73e5fe0d71e476a1096da97da3eb5f10f99'),
    ('email_advertising'::consent_kind, 'site-auth-advertising-2026-09-22-v1', 'Согласие на получение рекламы', '', '559b28859206b2ad54f1b2e8837cfac25bf8e650fe5782a9bf22d7bba56d9f6c')
)
INSERT INTO consent_revisions (
  id, kind, purpose, version, document_title, document_bytes, document_sha256,
  form_snapshot_bytes, form_sha256, created_at, published_at
)
SELECT r.id, r.kind, 'site_auth', '2026-09-22.auth-v1', r.document_title,
  decode(r.document_base64, 'base64'), r.document_sha256,
  a.form_bytes, 'be81dab5e57c012085ddebd2ae5ba3828af4c411ba9b34c538c07c079ab4e1c3',
  (transaction_timestamp() AT TIME ZONE 'UTC'),
  (transaction_timestamp() AT TIME ZONE 'UTC')
FROM revisions r CROSS JOIN artifacts a
WHERE NOT EXISTS (
  SELECT 1 FROM consent_revisions current
  WHERE current.kind = r.kind AND current.purpose = 'site_auth'
    AND current.published_at <= (transaction_timestamp() AT TIME ZONE 'UTC')
    AND (current.retired_at IS NULL OR current.retired_at > (transaction_timestamp() AT TIME ZONE 'UTC'))
);
